    def open_maximized(self):
        """Show the window filling the primary screen.

        Windows 11 does not round the corners of a maximized window -- the
        frame is placed past the screen edges, so the rounding DWM draws
        falls outside the visible area. Filling the screen was chosen over
        keeping the rounded corners; the two cannot both be had.

        The window is moved onto the primary screen before it is maximized,
        because a window maximizes onto whichever screen it currently sits
        on and Qt's default placement is not guaranteed to be that one.
        """
        screen = QGuiApplication.primaryScreen()
        if screen is not None:
            area = screen.availableGeometry()
            self.move(area.x() + 40, area.y() + 40)
        self.showMaximized()

