    # ── scanning ─────────────────────────────────────────────────────

    def refresh(self):
        if self._commit_worker is not None:
            return
        self._remember_typed()
        self._set_busy(True, "Reading the working tree…")
        worker = ScanWorker(self.repo, self)
        worker.scanned.connect(self._on_scanned)
        worker.failed.connect(self._on_scan_failed)
        self._track(worker)
        worker.start()

    def _remember_typed(self):
        for key, card in self.cards.items():
            if card.group.user_edited and card.group.message.strip():
                self.preserved[key] = card.group.message

    def _track(self, worker):
        self._workers.append(worker)
        worker.finished.connect(lambda: self._workers.remove(worker)
                                if worker in self._workers else None)

    def _on_scan_failed(self, message):
        self._set_busy(False)
        self.status_label.setText("Read failed")
        self._append_log(message)
        QMessageBox.critical(self, "Could not read the repository", message)

    def _on_scanned(self, state, groups, contents):
        self.state = state
        self.groups = groups
        self.contents = contents
        self._ignored_loaded = False

        for group in self.groups:
            saved = self.preserved.get(group.key)
            if saved:
                group.message = saved
                group.user_edited = True

        self._fill_header()
        self._fill_tree()
        self._fill_cards()
        self._set_busy(False)
        self._update_actions()

    def _fill_header(self):
        state = self.state
        marker = "detached @ " if state.detached else ""
        self.branch_label.setText(f"{marker}{state.branch}")
        bits = []
        if state.upstream:
            if state.ahead:
                bits.append(f"↑{state.ahead}")
            if state.behind:
                bits.append(f"↓{state.behind}")
            bits.append(f"· {state.upstream}")
        else:
            bits.append("· no upstream")
        self.sync_label.setText("  ".join(bits))

        blocked = state.blocked
        self.banner.setVisible(bool(blocked))
        if blocked:
            self.banner.setText(blocked)

    def _fill_tree(self):
        self._updating = True
        self.tree.clear()
        for index, group in enumerate(self.groups):
            parent = QTreeWidgetItem(self.tree)
            parent.setData(0, ROLE, ("group", group.key))
            badge = CIRCLED[index] if index < len(CIRCLED) else str(index + 1)
            parent.setText(0, f"{badge} {group.label}")
            parent.setText(1, "")
            parent.setText(2, files_label(len(group.changes)))
            parent.setForeground(0, theme.FG_TEXT)
            font = parent.font(0)
            font.setBold(True)
            parent.setFont(0, font)
            parent.setFlags(parent.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            parent.setCheckState(0, Qt.CheckState.Checked)

            for change in group.changes:
                child = QTreeWidgetItem(parent)
                child.setData(0, ROLE, ("file", change))
                child.setText(0, change.display)
                child.setToolTip(0, change.display)
                child.setText(1, theme.STATUS_LABELS.get(change.status,
                                                         change.status))
                child.setForeground(1, theme.STATUS_COLORS.get(
                    change.status, theme.FG_TEXT))
                child.setText(2, change.churn())
                child.setForeground(2, theme.FG_DIM)
                flags = child.flags() | Qt.ItemFlag.ItemIsUserCheckable
                if change.unmerged:
                    flags &= ~Qt.ItemFlag.ItemIsEnabled
                child.setFlags(flags)
                child.setCheckState(
                    0, Qt.CheckState.Unchecked if change.unmerged
                    else Qt.CheckState.Checked)
            parent.setExpanded(True)

        self.ignored_item = QTreeWidgetItem(self.tree)
        self.ignored_item.setData(0, ROLE, ("ignored", None))
        self.ignored_item.setText(0, "Ignored by .gitignore (expand to view)")
        self.ignored_item.setForeground(0, theme.FG_DIM)
        self.ignored_item.setChildIndicatorPolicy(
            QTreeWidgetItem.ChildIndicatorPolicy.ShowIndicator)
        self._updating = False

    def _fill_cards(self):
        for card in self.cards.values():
            card.setParent(None)
            card.deleteLater()
        self.cards.clear()
        while self.cards_layout.count() > 1:
            item = self.cards_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

        for index, group in enumerate(self.groups):
            card = GroupCard(index, group)
            card.edited.connect(lambda _key: self._update_actions())
            card.focused.connect(self._select_group)
            self.cards_layout.insertWidget(self.cards_layout.count() - 1, card)
            self.cards[group.key] = card

        if not self.groups:
            empty = QLabel("Working tree is clean — nothing to commit.")
            empty.setAlignment(Qt.AlignmentFlag.AlignCenter)
            empty.setStyleSheet(f"color: {theme.FG_DIM.name()}; padding: 20px;")
            self.cards_layout.insertWidget(self.cards_layout.count() - 1, empty)

    # ── tree interaction ─────────────────────────────────────────────

    def _iter_group_items(self):
        for index in range(self.tree.topLevelItemCount()):
            item = self.tree.topLevelItem(index)
            kind, payload = item.data(0, ROLE)
            if kind == "group":
                yield item, payload

    def _group_item(self, key):
        for item, group_key in self._iter_group_items():
            if group_key == key:
                return item
        return None

    def _selected_paths(self, item) -> list[str]:
        paths = []
        for row in range(item.childCount()):
            child = item.child(row)
            if child.checkState(0) == Qt.CheckState.Checked:
                _kind, change = child.data(0, ROLE)
                paths.append(change.path)
        return paths

    def _on_item_changed(self, item, column):
        if self._updating or column != 0:
            return
        data = item.data(0, ROLE)
        if not data:
            return
        kind, _payload = data
        self._updating = True
        try:
            if kind == "group":
                target = item.checkState(0)
                if target != Qt.CheckState.PartiallyChecked:
                    for row in range(item.childCount()):
                        child = item.child(row)
                        if child.flags() & Qt.ItemFlag.ItemIsEnabled:
                            child.setCheckState(0, target)
            elif kind == "file":
                parent = item.parent()
                if parent is not None:
                    self._sync_parent_state(parent)
        finally:
            self._updating = False
        self._sync_messages()
        self._update_actions()

    @staticmethod
    def _sync_parent_state(parent):
        total = parent.childCount()
        checked = sum(1 for row in range(total)
                      if parent.child(row).checkState(0) == Qt.CheckState.Checked)
        if checked == 0:
            parent.setCheckState(0, Qt.CheckState.Unchecked)
        elif checked == total:
            parent.setCheckState(0, Qt.CheckState.Checked)
        else:
            parent.setCheckState(0, Qt.CheckState.PartiallyChecked)

    def _set_all_checked(self, checked: bool):
        state = Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked
        self._updating = True
        try:
            for item, _key in self._iter_group_items():
                for row in range(item.childCount()):
                    child = item.child(row)
                    if child.flags() & Qt.ItemFlag.ItemIsEnabled:
                        child.setCheckState(0, state)
                self._sync_parent_state(item)
        finally:
            self._updating = False
        self._sync_messages()
        self._update_actions()

    def _sync_messages(self):
        """Regenerate every auto message the user has not taken over."""
        for item, key in self._iter_group_items():
            card = self.cards.get(key)
            if card is None:
                continue
            paths = self._selected_paths(item)
            group = card.group
            if group.auto and not group.user_edited:
                card.set_message(rules.message_for(group, self.contents, paths))
            card.set_selected_count(len(paths))

    def _select_group(self, key):
        item = self._group_item(key)
        if item is not None:
            self.tree.setCurrentItem(item)

    def _on_item_selected(self, current, _previous):
        if current is None:
            return
        data = current.data(0, ROLE)
        if not data:
            return
        kind, payload = data
        if kind == "file":
            self._load_diff(payload)
        elif kind == "group":
            card = self.cards.get(payload)
            if card is not None:
                self.cards_area.ensureWidgetVisible(card)

    def _on_item_expanded(self, item):
        data = item.data(0, ROLE)
        if not data or data[0] != "ignored" or self._ignored_loaded:
            return
        self._ignored_loaded = True
        placeholder = QTreeWidgetItem(item)
        placeholder.setText(0, "Reading…")
        placeholder.setForeground(0, theme.FG_DIM)
        worker = IgnoredWorker(self.repo, self)
        worker.listed.connect(self._on_ignored)
        worker.failed.connect(lambda msg: self._append_log(msg))
        self._track(worker)
        worker.start()

    def _on_ignored(self, paths, total):
        item = getattr(self, "ignored_item", None)
        if item is None:
            return
        self._updating = True
        try:
            item.takeChildren()
            for path in paths:
                child = QTreeWidgetItem(item)
                child.setText(0, gitcmd.for_display(path))
                child.setText(1, "ignored")
                child.setForeground(0, theme.FG_DIM)
                child.setForeground(1, theme.FG_DIM)
            item.setText(
                0, f"Ignored by .gitignore — {total} items, never committed")
            if total > len(paths):
                more = QTreeWidgetItem(item)
                more.setText(0, f"… {total - len(paths)} more not listed")
                more.setForeground(0, theme.FG_DIM)
        finally:
            self._updating = False

    # ── diff preview ─────────────────────────────────────────────────

    def _load_diff(self, change):
        self._diff_generation += 1
        generation = self._diff_generation
        self.note_view.setText("Reading…")
        self.preview.setCurrentWidget(self.note_view)
        worker = DiffWorker(self.repo, change, generation, self)
        worker.ready.connect(self._on_diff_ready)
        worker.failed.connect(self._on_diff_failed)
        self._track(worker)
        worker.start()

    def _on_diff_ready(self, generation, _path, kind, payload):
        if generation != self._diff_generation:
            return                      # a newer selection already won
        if kind == "text":
            self.diff_view.setPlainText(payload)
            self.preview.setCurrentWidget(self.diff_view)
        elif kind == "image":
            self.image_view.show_image(payload)
            self.preview.setCurrentWidget(self.image_view)
        else:
            self.note_view.setText(payload)
            self.preview.setCurrentWidget(self.note_view)

    def _on_diff_failed(self, generation, message):
        if generation != self._diff_generation:
            return
        self.note_view.setText(message)
        self.preview.setCurrentWidget(self.note_view)

    # ── the plan ─────────────────────────────────────────────────────

    def _build_plan(self):
        """[(message, [paths], group)] for the groups with something ticked."""
        plan = []
        for item, key in self._iter_group_items():
            card = self.cards.get(key)
            if card is None:
                continue
            paths = self._selected_paths(item)
            if paths:
                plan.append((card.group.message.strip(), paths, card.group))
        return plan

    def _update_actions(self):
        busy = self._commit_worker is not None
        state = self.state
        blocked = state.blocked if state else "Reading…"
        plan = self._build_plan() if state else []

        total_files = sum(len(paths) for _m, paths, _g in plan)
        unready = [group for _m, _p, group in plan if not group.ready()]

        # Deliberately NOT gated on `unready`: a click on a group that still
        # needs a description is answered by jumping to that box, which is
        # more use than a button that cannot be pressed at all. See the
        # module docstring.
        can_act = bool(plan) and not blocked and not busy
        self.commit_button.setEnabled(can_act)
        self.commit_push_button.setEnabled(can_act)
        self.push_only_button.setEnabled(
            not busy and state is not None and not state.detached
            and (state.ahead > 0 or not state.upstream))
        self.refresh_button.setEnabled(not busy)
        self.check_all.setEnabled(not busy)
        self.check_none.setEnabled(not busy)

        if busy:
            return
        if blocked:
            self.status_label.setText(blocked)
        elif not self.groups:
            self.status_label.setText("Working tree is clean.")
        elif not plan:
            self.status_label.setText("Nothing ticked.")
        elif unready:
            names = ", ".join(group.label for group in unready)
            self.status_label.setText(
                f"{len(unready)} group(s) still need a message: {names}. "
                f"Type one, or press Commit to jump to it.")
        else:
            self.status_label.setText(
                f"{len(plan)} commit(s) · {total_files} file(s) · all ready.")

    # ── committing ───────────────────────────────────────────────────

    def _start_commit(self, push: bool):
        plan = self._build_plan()
        if not plan:
            return
        unready = [group for _m, _p, group in plan if not group.ready()]
        if unready:
            self._demand_description(unready)
            return
        if not self._confirm(plan, push):
            return
        expected = {change.path: change.status for change in self.state.changes}
        self.log.clear()
        self._set_busy(True, "Committing…")
        self.progress.setRange(0, len(plan) + (1 if push else 0))
        self.progress.setValue(0)
        self.progress.show()

        worker = CommitWorker(
            self.repo, [(message, paths) for message, paths, _g in plan],
            push, expected, self)
        worker.log.connect(self._append_log)
        worker.progress.connect(lambda done, total: self.progress.setValue(done))
        worker.done.connect(self._on_commit_done)
        self._commit_worker = worker
        self._update_actions()
        worker.start()

    def _demand_description(self, unready):
        """Answer a refused click by showing exactly what is missing.

        Nothing is committed, the offending cards are outlined, and the caret
        lands in the first one. The log gets the reason in full, because the
        status bar is one line and this is the question people hit most.
        """
        for group in unready:
            card = self.cards.get(group.key)
            if card is not None:
                card.set_alert(True)
        first = self.cards.get(unready[0].key)
        if first is not None:
            self.cards_area.ensureWidgetVisible(first)
            first.demand_input()
        names = ", ".join(group.label for group in unready)
        self.status_label.setText(
            f"Nothing committed — {len(unready)} group(s) still need a "
            f"description: {names}. Type one in the highlighted box.")
        self._append_log(
            f"Refused: {names} still carries only its prefix. "
            f"post: and update: are filled in automatically from the post "
            f"titles; config:, fix: and remove: describe intent, so they are "
            f"yours to write.")

    def _confirm(self, plan, push: bool) -> bool:
        lines = []
        for index, (message, paths, _group) in enumerate(plan):
            badge = CIRCLED[index] if index < len(CIRCLED) else str(index + 1)
            lines.append(f"{badge} {message}   ({files_label(len(paths))})")

        warning = ""
        removing = sum(len(p) for _m, p, g in plan if g.kind == "remove")
        if removing:
            warning += (f"\n⚠ Includes {removing} deletion(s); getting them "
                        f"back afterwards needs git.")
        if push and self.state.behind:
            warning += (f"\n⚠ The remote is {self.state.behind} commit(s) "
                        f"ahead of you, so the push will most likely be "
                        f"rejected. Consider `git pull --rebase` first.")
        if push:
            warning += ("\n\nPushing starts the GitHub Actions build and "
                        "deploys the site.")

        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Question)
        box.setWindowTitle("Confirm commit" + (" and push" if push else ""))
        box.setText(f"Create {len(plan)} commit(s)"
                    + (", then push to origin:" if push else ":"))
        box.setInformativeText("\n".join(lines) + warning)
        box.setStandardButtons(QMessageBox.StandardButton.Ok
                               | QMessageBox.StandardButton.Cancel)
        box.setDefaultButton(QMessageBox.StandardButton.Cancel)
        return box.exec() == QMessageBox.StandardButton.Ok

    def _on_push_only(self):
        if self.state is None:
            return
        note = ""
        if self.state.behind:
            note = (f"\n⚠ The remote is {self.state.behind} commit(s) ahead of "
                    f"you, so the push will most likely be rejected.")
        answer = QMessageBox.question(
            self, "Confirm push",
            f"Push {self.state.branch} to origin — "
            f"{self.state.ahead} local commit(s) ahead."
            f"{note}\n\nPushing starts the GitHub Actions deploy.",
            QMessageBox.StandardButton.Ok | QMessageBox.StandardButton.Cancel,
            QMessageBox.StandardButton.Cancel)
        if answer != QMessageBox.StandardButton.Ok:
            return
        self.log.clear()
        self._set_busy(True, "Pushing…")
        self.progress.setRange(0, 1)
        self.progress.setValue(0)
        self.progress.show()
        worker = CommitWorker(self.repo, [], True, {}, self)
        worker.log.connect(self._append_log)
        worker.progress.connect(lambda done, _t: self.progress.setValue(done))
        worker.done.connect(self._on_commit_done)
        self._commit_worker = worker
        self._update_actions()
        worker.start()

    def _on_commit_done(self, ok: bool, summary: str):
        self._commit_worker = None
        self.progress.hide()
        self._append_log(("✔ " if ok else "✘ ") + summary.replace("\n", " "))
        self.preserved.clear()
        self._set_busy(False)
        if ok:
            self.status_label.setText(summary)
        else:
            QMessageBox.warning(self, "Did not finish", summary)
        self.refresh()

    # ── odds and ends ────────────────────────────────────────────────

    def _append_log(self, line: str):
        self.log.appendPlainText(line)
        bar = self.log.verticalScrollBar()
        bar.setValue(bar.maximum())

    def _set_busy(self, busy: bool, message: str = ""):
        if busy and message:
            self.status_label.setText(message)
        self.setCursor(Qt.CursorShape.BusyCursor if busy
                       else Qt.CursorShape.ArrowCursor)
        if not busy:
            self._update_actions()

    def closeEvent(self, event):
        if self._commit_worker is not None and self._commit_worker.isRunning():
            answer = QMessageBox.question(
                self, "Still working",
                "A commit or push is still running. Close anyway?\n"
                "Commits already made are kept; the one in flight is cut off.",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No)
            if answer != QMessageBox.StandardButton.Yes:
                event.ignore()
                return
            self._commit_worker.cancel()
            self._commit_worker.wait(5000)

        unsaved = [card for card in self.cards.values()
                   if card.group.user_edited and card.group.message.strip()
                   and not card.group.auto]
        if unsaved and self._commit_worker is None:
            answer = QMessageBox.question(
                self, "Unsaved messages",
                f"{len(unsaved)} hand-written commit message(s) have not been "
                f"committed and will be lost.\nClose anyway?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No)
            if answer != QMessageBox.StandardButton.Yes:
                event.ignore()
                return

        for worker in list(self._workers):
            worker.requestInterruption()
            worker.wait(2000)
        event.accept()
